def eat(number, need, remaining):
    total = number + (need - remaining)
    return [total, remaining]

def do_algebra(operator, operand):
    if len(operand) == 1:
        return operand[0]
    else:
        return str(sum([int(i) for i in operand]))

import re
def solve(s):
  res = ''
  for i in range(len(s)):
    if s[i].isalpha():
      res += chr(32 + ord(s[i]) - ord('A'))
    else:
      res += s[i]
  return (res)

import hashlib
def string_to_md5(text):
  if not text:
    return None
  else:
    return hashlib.md5(text.encode()).hexdigest()

def generate_integers(a, b):
    result = []
    for i in range(a, b + 1):
        if (i % 2 == 0):
            result.append(i)
    return result
